(gen_random_uuid(), 'medellin', 'local_legend', 'The Eternal Spring label is climate and marketing', 'Medellín is often called the City of Eternal Spring. Use the nickname as a climate clue, not a reason to skip real weather checks.', 'Medellin reference', '🌸', null, '{"source": "https://en.wikipedia.org/wiki/Medell%C3%ADn"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://en.wikipedia.org/wiki/Medell%C3%ADn', 'cc0', 180, 'reference_only'),
(gen_random_uuid(), 'medellin', 'local_legend', 'Metrocable made the hillside visible', 'Medellín’s cable cars are mobility infrastructure and city symbol at once. Treat the ride as public transit, not a theme-park loop.', 'Metrocable reference', '🚡', null, '{"source": "https://en.wikipedia.org/wiki/Metrocable_(Medell%C3%ADn)"}'::jsonb, '{"accessed": "2026-08-02", "confidence": "documented", "profile": "local-expert-addons", "review_state": "source_checked", "rights": "original_lore_copy", "wave": "2026-08"}'::jsonb, 'https://en.wikipedia.org/wiki/Metrocable_(Medell%C3%ADn)', 'cc0', 181, 'reference_only'),
